import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[] a = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        List<Integer> leftPart = new ArrayList<>();
        List<Integer> rightPart = new ArrayList<>();
        int midPoint = n / 2;

        generateLeft(0, 0, a, m, midPoint, leftPart);
        generateRight(midPoint, 0, a, m, n, rightPart);

        Set<Integer> leftSet = new HashSet<>(leftPart);
        List<Integer> uniqueLeftPart = new ArrayList<>(leftSet);
        Collections.sort(uniqueLeftPart);

        int maxFound = 0;

        for (int val : rightPart) {
            int idx = lowerBound(uniqueLeftPart, m - val);
            if (idx > 0) {
                int candidateSum = uniqueLeftPart.get(idx - 1) + val;
                if (candidateSum > maxFound) {
                    maxFound = candidateSum;
                }
            } else {
                if (val > maxFound) {
                    maxFound = val;
                }
            }
        }
        System.out.println(maxFound);
    }

    static void generateLeft(int i, int total, int[] a, int m, int midPoint, List<Integer> leftPart) {
        if (i == midPoint) {
            leftPart.add(total);
        } else {
            generateLeft(i + 1, (total + a[i]) % m, a, m, midPoint, leftPart);
            generateLeft(i + 1, total, a, m, midPoint, leftPart);
        }
    }

    static void generateRight(int i, int total, int[] a, int m, int n, List<Integer> rightPart) {
        if (i == n) {
            rightPart.add(total);
        } else {
            generateRight(i + 1, (total + a[i]) % m, a, m, n, rightPart);
            generateRight(i + 1, total, a, m, n, rightPart);
        }
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}
